using System;using System.IO;using System.Collections.Generic;using System.Drawing;
class TavernWeatherChecks{static void Main(){var seen=new HashSet<string>();foreach(var phase in new[]{"morning","dusk","night"})foreach(var weather in new[]{"clear","cloudy","rain"}){var file=TavernTime.BackgroundFile(new TavernTimeState{phase=phase,weather=weather});if(!seen.Add(file))throw new Exception("duplicate background");using(var image=Image.FromFile(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"assets","waystation",file)))if(image.Width<1000)throw new Exception("invalid image");Console.WriteLine(phase+" / "+weather+" -> "+file);}var save=new Save();var random=new Random(7);for(int i=0;i<30;i++){var before=TavernTime.State(save).phase;TavernTime.Advance(save,random);var after=save.tavernTime.phase;if(after!=(before=="morning"?"dusk":before=="dusk"?"night":"morning"))throw new Exception("cycle");}Console.WriteLine("PASS 9 unique background assets and 30 time transitions");}}
